        // ────────────────────────────────────────────
        // Section Collection
        // ────────────────────────────────────────────

        private void CollectFrames()
        {
            _frames.Clear();
            if (_content == null)
                return;

            _frames.AddRange(_content.GetComponentsInChildren<UIBaseFrame>(true));
        }

        private void CollectSections()
        {
            _sections.Clear();
            foreach (var frame in _frames)
            {
                if (frame is IUIScrollSection section)
                    _sections.Add(section);
            }
        }

        // ────────────────────────────────────────────
        // Logical Row Building
        // ────────────────────────────────────────────

        private void BuildLogicalRows()
        {
            _logicalRows.Clear();
            float pos = _padding.top;

            for (int s = 0; s < _sections.Count; s++)
            {
                var section = _sections[s];
                var frame = (UIBaseFrame)_sections[s];
                int rowCount = section.GetLogicalRowCount();
                float rowSpacing = section.GetLogicalRowSpacing();

                for (int r = 0; r < rowCount; r++)
                {
                    float rowSize = section.GetLogicalRowMainAxisSize(r);
                    _logicalRows.Add(new ScrollLogicalRow
                    {
                        Section = section,
                        Frame = frame,
                        LocalRowIndex = r,
                        MainAxisPosition = pos,
                        MainAxisSize = rowSize,
                        IsVisible = false
                    });
                    pos += rowSize;
                    if (r < rowCount - 1) pos += rowSpacing;
                }

                if (s < _sections.Count - 1)
                    pos += _sectionSpacing;
            }

            _totalContentSize = pos + _padding.bottom;
        }

        private void RebuildLayoutCore()
        {
            BuildLogicalRows();
            SetContentMainAxisSize(_totalContentSize);
            ApplySectionLayouts();
        }

        private void ApplySectionLayouts()
        {
            float crossSize = GetCrossAxisSize();
            float pos = _padding.top;

            for (int s = 0; s < _sections.Count; s++)
            {
                var section = _sections[s];
                section.ApplySectionLayout(new UIUIScrollSectionLayout(
                    _content, _direction, pos, crossSize));

                // section 전체 높이 건너뛰기
                int rowCount = section.GetLogicalRowCount();
                float rowSpacing = section.GetLogicalRowSpacing();
                for (int r = 0; r < rowCount; r++)
                {
                    pos += section.GetLogicalRowMainAxisSize(r);
                    if (r < rowCount - 1) pos += rowSpacing;
                }

                if (s < _sections.Count - 1)
                    pos += _sectionSpacing;
            }
        }

        // ────────────────────────────────────────────
        // Virtualization (Logical Row 단위)
        // ────────────────────────────────────────────

        private void OnScrollChanged(Vector2 _) { if (_initialized) UpdateVisibleRows(); }

        private void UpdateVisibleRows()
        {
            if (_logicalRows.Count == 0) return;

            float scrollPos = GetScrollPosition();
            float vpSize = GetViewportSize();
            float crossSize = GetCrossAxisSize();

            int first = FindFirst(scrollPos);
            int last = FindLast(scrollPos, vpSize);
            first = Mathf.Max(0, first - _bufferRows);
            last = Mathf.Min(_logicalRows.Count - 1, last + _bufferRows);

            // 이탈
            if (_prevFirst >= 0)
            {
                for (int i = _prevFirst; i <= _prevLast; i++)
                {
                    if (i < first || i > last)
                    {
                        var row = _logicalRows[i];
                        if (row.IsVisible)
                        {
                            row.Section.UnbindRow(row.LocalRowIndex);
                            row.IsVisible = false;
                            _logicalRows[i] = row;
                        }
                    }
                }
            }

            // 진입
            for (int i = first; i <= last; i++)
            {
                var row = _logicalRows[i];
                if (!row.IsVisible)
                {
                    row.Section.BindRow(new UIScrollRowLayout(
                        _content, _direction,
                        row.LocalRowIndex, row.MainAxisPosition, row.MainAxisSize, crossSize));
                    row.IsVisible = true;
                    _logicalRows[i] = row;
                }
            }

            _prevFirst = first;
            _prevLast = last;
        }

        // ────────────────────────────────────────────
        // Binary Search
        // ────────────────────────────────────────────

        private int FindFirst(float scrollPos)
        {
            int lo = 0, hi = _logicalRows.Count - 1;
            while (lo < hi)
            {
                int mid = (lo + hi) / 2;
                if (_logicalRows[mid].MainAxisPosition + _logicalRows[mid].MainAxisSize <= scrollPos)
                    lo = mid + 1;
                else hi = mid;
            }
            return lo;
        }

        private int FindLast(float scrollPos, float vpSize)
        {
            float end = scrollPos + vpSize;
            int lo = 0, hi = _logicalRows.Count - 1;
            while (lo < hi)
            {
                int mid = (lo + hi + 1) / 2;
                if (_logicalRows[mid].MainAxisPosition >= end) hi = mid - 1;
                else lo = mid;
            }
            return lo;
        }

